class Solution:
    def search(self, reader: 'ArrayReader', target: int) -> int:
        low, high = 0, 1
        while reader.get(high) < target:
            low, high = high + 1, high * 2
        while low < high:
            middle = (low + high) // 2
            if reader.get(middle) < target:
                low = middle + 1
            else:
                high = middle
        return low if reader.get(low) == target else -1
